580.source:
.yoggies-wrapper {
max-width:1200px;
margin:auto;
padding:40px 20px;
font-family:"Ambra Sans", sans-serif;
color:#000;
}
.yoggies-row {
display:flex;
align-items:flex-start;
gap:50px;
margin-bottom:50px;
}
.yoggies-row.reverse {
flex-direction:row-reverse;
}
.yoggies-text,
.yoggies-image {
width:50%;
}
/* Obrázek má pevný poměr stran a nedominuje výšce řádku */
.yoggies-image {
aspect-ratio:4/3;
border-radius:14px;
overflow:hidden;
}
.yoggies-image img {
display:block;
width:100%;
height:100%;
object-fit:cover;
border-radius:14px;
}
.yoggies-text h2 {
font-size:30px;
line-height:1.3;
color:#3b1f00;
margin-bottom:14px;
}
.yoggies-text p {
font-size:14px;
line-height:1.8;
margin-bottom:14px;
}
/* STŘEDNÍ SEKCE */
.yoggies-box-title {
text-align:center;
margin:60px 0 35px;
}
.yoggies-box-title h2 {
font-size:30px;
color:#3b1f00;
margin-bottom:14px;
}
.yoggies-box-title p {
font-size:14px;
}
/* GRID */
.yoggies-products {
display:grid;
grid-template-columns:repeat(4, 1fr);
gap:14px;
}
/* POSLEDNÍ KARTIČKA UPROSTŘED (desktop, 4 sloupce) */
.yoggies-card:last-child {
grid-column:2 / span 2;
width:50%;
justify-self:center;
}
.yoggies-card {
background:#faf7f2;
border-radius:14px;
padding:14px;
text-align:center;
min-height:125px;
display:flex;
flex-direction:column;
justify-content:center;
}
.yoggies-card h3 {
color:#3b1f00;
font-size:14px;
line-height:1.35;
margin:0 0 6px;
}
.yoggies-card span {
font-size:14px;
font-weight:bold;
margin-bottom:8px;
}
.yoggies-card p {
font-size:13px;
line-height:1.5;
margin:0;
}
/* ZÁVĚR */
.yoggies-highlight {
color:#3b1f00;
font-weight:bold;
font-size:16px!important;
}
/* TABLET / VĚTŠÍ MOBIL (601–900px) */
@media(max-width:900px){
.yoggies-products {
grid-template-columns:repeat(2,1fr);
}
.yoggies-card:last-child {
grid-column:1 / span 2;
width:60%;
justify-self:center;
}
}
/* MOBIL */
@media(max-width:600px){
.yoggies-row,
.yoggies-row.reverse {
flex-direction:column;
gap:24px;
margin-bottom:40px;
}
.yoggies-text,
.yoggies-image {
width:100%;
}
.yoggies-image {
aspect-ratio:16/10;
}
.yoggies-products {
grid-template-columns:1fr;
gap:12px;
}
.yoggies-card:last-child {
grid-column:auto;
width:auto;
justify-self:stretch;
}
.yoggies-text h2,
.yoggies-box-title h2 {
font-size:24px;
}
}

